package com.empiretycoon.idleconquest.ui

import android.content.Context
import android.graphics.BitmapFactory
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Paint
import android.graphics.RectF
import android.view.MotionEvent
import android.view.View
import com.empiretycoon.idleconquest.art.*
import com.empiretycoon.idleconquest.game.*
import java.util.Locale

class BusinessShowcaseView(context:Context):View(context){
 private val resolver=BusinessArtResolver(context);private val sprites=ProceduralBusinessSpriteRenderer(context);private val portraits=ManagerPortraitRenderer(context);private val permanentIcons=PermanentUpgradeIconRenderer(context);private val missionBadges=MissionBadgeRenderer(context);private val saveStore=GameSaveStore(context);private var gameState:GameState
 private val paint=Paint(Paint.ANTI_ALIAS_FLAG);private val upgradeRects=mutableListOf<RectF>();private val managerRects=mutableListOf<Pair<String,RectF>>();private val permanentRects=mutableListOf<Pair<String,RectF>>();private val missionRects=mutableListOf<Pair<String,RectF>>();private val modeRects=mutableListOf<Pair<BuyMode,RectF>>();private var buyMode=BuyMode.X1;private var lastFrame=0L;private var lastSave=0L;private var banner:String?=null;private var bannerUntil=0L;private var highlighted:String?=null
 init{val r=saveStore.restore();gameState=r.state;if(r.offlineEarnings>0)show("WELCOME BACK +$ ${fmt(r.offlineEarnings)}",6_000_000_000L);isClickable=true;keepScreenOn=true}
 override fun onDraw(c:Canvas){super.onDraw(c);update();autosave();c.drawColor(Color.rgb(8,10,24));val m=width*.04f;val hh=height*.09f;val mh=height*.045f;val qh=height*.07f;hud(c,RectF(m,m,width-m,m+hh));modes(c,RectF(m,m+hh+5,width-m,m+hh+5+mh));missions(c,RectF(m,m+hh+mh+10,width-m,m+hh+mh+10+qh));val now=System.nanoTime();val bh=if(banner!=null&&now<bannerUntil)height*.038f else 0f;if(bh>0)banner(c,RectF(m,m+hh+mh+qh+16,width-m,m+hh+mh+qh+16+bh),banner!!);upgradeRects.clear();managerRects.clear();permanentRects.clear();val top=m+hh+mh+qh+m+bh;val gap=m*.4f;val ch=(height-top-m-gap*3)/4;gameState.businesses.indices.forEach{i->card(c,RectF(m,top+i*(ch+gap),width-m,top+i*(ch+gap)+ch),i,now)};postInvalidateOnAnimation()}
 private fun update(){val n=System.nanoTime();if(lastFrame!=0L)gameState.tick(((n-lastFrame)/1e9).coerceAtMost(.25));lastFrame=n}
 private fun autosave(){val n=System.nanoTime();if(lastSave==0L||n-lastSave>=10_000_000_000L){saveStore.save(gameState);lastSave=n}}
 fun persistNow()=saveStore.save(gameState)
 private fun hud(c:Canvas,r:RectF){paint.style=Paint.Style.FILL;paint.color=Color.rgb(13,17,36);c.drawRoundRect(r,28f,28f,paint);paint.color=Color.rgb(245,201,92);paint.textSize=width*.04f;paint.isFakeBoldText=true;c.drawText("EMPIRE TYCOON",r.left+22,r.top+r.height()*.38f,paint);paint.isFakeBoldText=false;paint.textSize=width*.03f;paint.color=Color.WHITE;c.drawText("$ ${fmt(gameState.cash)}",r.left+22,r.bottom-15,paint);paint.color=Color.rgb(92,230,145);c.drawText("+${fmt(gameState.totalIncomePerSecond)}/s",r.centerX()-5,r.bottom-15,paint);paint.textAlign=Paint.Align.RIGHT;paint.color=Color.rgb(120,187,255);c.drawText("◆ ${gameState.gems}",r.right-22,r.bottom-15,paint);paint.textAlign=Paint.Align.LEFT}
 private fun modes(c:Canvas,r:RectF){modeRects.clear();val gap=7f;val w=(r.width()-gap*3)/4;BuyMode.entries.forEachIndexed{i,x->val b=RectF(r.left+i*(w+gap),r.top,r.left+i*(w+gap)+w,r.bottom);modeRects+=x to b;paint.style=Paint.Style.FILL;paint.color=if(x==buyMode)Color.rgb(43,121,220)else Color.rgb(29,39,70);c.drawRoundRect(b,16f,16f,paint);paint.color=Color.WHITE;paint.textAlign=Paint.Align.CENTER;paint.isFakeBoldText=true;paint.textSize=width*.024f;c.drawText(if(x==BuyMode.MAX)"MAX" else "×${x.name.drop(1)}",b.centerX(),b.centerY()+paint.textSize*.35f,paint)};paint.textAlign=Paint.Align.LEFT;paint.isFakeBoldText=false}
 private fun missions(c:Canvas,r:RectF){missionRects.clear();paint.style=Paint.Style.FILL;paint.color=Color.rgb(12,17,36);c.drawRoundRect(r,18f,18f,paint);val list=gameState.missions;val gap=5f;val w=(r.width()-gap*5)/6f;list.forEachIndexed{i,m->val rr=RectF(r.left+i*(w+gap),r.top,r.left+i*(w+gap)+w,r.bottom);val state=when{m.claimed->"claimed";m.completed->"complete";m.progress>0->"active";else->"locked"};missionBadges.draw(c,rr,m.definition,state);missionRects+=m.definition.id to rr}}
 private fun banner(c:Canvas,r:RectF,t:String){paint.style=Paint.Style.FILL;paint.color=Color.rgb(95,67,18);c.drawRoundRect(r,16f,16f,paint);paint.color=Color.rgb(255,220,112);paint.textAlign=Paint.Align.CENTER;paint.isFakeBoldText=true;paint.textSize=width*.023f;c.drawText(t,r.centerX(),r.centerY()+paint.textSize*.35f,paint);paint.textAlign=Paint.Align.LEFT;paint.isFakeBoldText=false}
 private fun card(c:Canvas,r:RectF,i:Int,now:Long){val b=gameState.businesses[i];val tier=gameState.tierFor(b.level);val active=highlighted==b.id&&now<bannerUntil;val state=if(active)"milestone" else "default";val art=resolver.resolve(b.id,tier,state=state);paint.style=Paint.Style.FILL;paint.color=if(active)Color.rgb(38,30,54)else Color.rgb(15,20,42);c.drawRoundRect(r,24f,24f,paint);val inset=10f;val artR=RectF(r.left+inset,r.top+inset,r.left+r.width()*.24f,r.bottom-inset);if(art.layerPaths.isNotEmpty())art.layerPaths.forEach{p->context.assets.open(p).use{BitmapFactory.decodeStream(it)?.let{x->c.drawBitmap(x,null,artR,paint)}}}else sprites.draw(c,artR,b.id,tier,state);val x=r.left+r.width()*.28f;val rightColLeft=r.right-r.width()*.19f;val manager=gameState.managerFor(b.id)!!;val pr=RectF(rightColLeft,r.top+inset,r.right-inset,r.top+r.height()*.45f);val managerState=when{manager.hired->"hired";b.level>=manager.definition.unlockLevel->"available";else->"locked"};portraits.draw(c,pr,manager.definition,managerState);managerRects+=manager.definition.id to pr;drawPermanentUpgrades(c,r,b,rightColLeft,inset);paint.style=Paint.Style.FILL;paint.color=Color.WHITE;paint.textSize=width*.027f;paint.isFakeBoldText=true;c.drawText(b.displayName,x,r.top+r.height()*.18f,paint);paint.isFakeBoldText=false;paint.textSize=width*.0195f;paint.color=Color.rgb(188,198,225);c.drawText("Lv.${b.level} • ${tier.uppercase(Locale.US)} • ×${mult(b.productionMultiplier)}",x,r.top+r.height()*.31f,paint);paint.color=Color.rgb(92,230,145);c.drawText("+${fmt(gameState.incomeFor(b))}/s",x,r.top+r.height()*.44f,paint);paint.color=Color.rgb(120,187,255);val mt=if(manager.hired)"${manager.definition.name} ×${mult(manager.definition.incomeMultiplier)}" else if(b.level>=manager.definition.unlockLevel)"HIRE ${manager.definition.name} $${fmt(manager.definition.cost)}" else "MANAGER Lv.${manager.definition.unlockLevel}";c.drawText(mt,x,r.top+r.height()*.57f,paint);val pm=gameState.permanentIncomeMultiplier(b.id);val cm=gameState.permanentCostMultiplier(b.id);paint.color=Color.rgb(245,201,92);c.drawText("PERM income ×${mult(pm)} • cost ×${mult(cm)}",x,r.top+r.height()*.68f,paint);val br=RectF(x,r.bottom-r.height()*.22f,rightColLeft-8f,r.bottom-inset);upgradeRects+=br;upgradeButton(c,br,i)}
 private fun drawPermanentUpgrades(c:Canvas,r:RectF,b:BusinessState,left:Float,inset:Float){val list=gameState.permanentUpgrades.filter{it.definition.businessId==b.id};val gap=5f;val top=r.top+r.height()*.49f;val h=(r.bottom-inset-top-gap)/2f;list.forEachIndexed{idx,u->val rr=RectF(left,top+idx*(h+gap),r.right-inset,top+idx*(h+gap)+h);val state=when{u.purchased->"purchased";b.level>=u.definition.unlockLevel->"available";else->"locked"};permanentIcons.draw(c,rr,u.definition.id,state);permanentRects+=u.definition.id to rr}}
 private fun upgradeButton(c:Canvas,r:RectF,i:Int){val q=gameState.quoteUpgrade(i,buyMode);val on=gameState.canUpgrade(i,buyMode);paint.style=Paint.Style.FILL;paint.color=if(on)Color.rgb(42,166,105)else Color.rgb(59,68,91);c.drawRoundRect(r,18f,18f,paint);paint.color=Color.WHITE;paint.textAlign=Paint.Align.CENTER;paint.isFakeBoldText=true;paint.textSize=width*.0205f;c.drawText(if(q.levels>0)"+${q.levels} $ ${fmt(q.cost)}" else "MAX",r.centerX(),r.centerY()+paint.textSize*.35f,paint);paint.textAlign=Paint.Align.LEFT;paint.isFakeBoldText=false}
 override fun onTouchEvent(e:MotionEvent):Boolean{if(e.action==MotionEvent.ACTION_UP){missionRects.firstOrNull{it.second.contains(e.x,e.y)}?.let{pair->val state=gameState.missions.first{it.definition.id==pair.first};if(state.completed&&!state.claimed){val result=gameState.claimMission(pair.first);if(result.claimed){val rw=result.mission!!.reward;show("MISSION COMPLETE! ${result.mission.title} +${if(rw.type==MissionRewardType.CASH)"$ ${fmt(rw.amount)}" else "◆ ${rw.amount.toInt()}"}",5_000_000_000L);saveStore.save(gameState)}}else{show("${state.definition.title} ${fmt(state.progress)}/${fmt(state.definition.target)}",3_000_000_000L)};performClick();invalidate();return true};modeRects.firstOrNull{it.second.contains(e.x,e.y)}?.let{buyMode=it.first;performClick();invalidate();return true};permanentRects.firstOrNull{it.second.contains(e.x,e.y)}?.let{val result=gameState.buyPermanentUpgrade(it.first);if(result.purchased){show("PERMANENT UPGRADE! ${result.upgrade!!.name}",5_000_000_000L);saveStore.save(gameState)}else{PermanentUpgradeCatalog.all.firstOrNull{u->u.id==it.first}?.let{u->show("${u.name} • Lv.${u.unlockLevel} • $${fmt(u.cost)}",3_000_000_000L)}};performClick();invalidate();return true};managerRects.firstOrNull{it.second.contains(e.x,e.y)}?.let{val h=gameState.hire(it.first);if(h.hired){show("MANAGER HIRED! ${h.manager!!.name} ×${mult(h.manager.incomeMultiplier)}",5_000_000_000L);saveStore.save(gameState)};performClick();invalidate();return true};val i=upgradeRects.indexOfFirst{it.contains(e.x,e.y)};if(i>=0){val before=gameState.businesses[i];val result=gameState.upgrade(i,buyMode);if(result.upgraded){result.reachedMilestones.lastOrNull()?.let{m->highlighted=before.id;show("MILESTONE! ${before.displayName} Lv.${m.level} ×${mult(m.multiplier)}",5_000_000_000L)};saveStore.save(gameState);performClick();invalidate()}}};return true}
 override fun performClick():Boolean{super.performClick();return true}
 private fun show(t:String,d:Long){banner=t;bannerUntil=System.nanoTime()+d}
 private fun mult(v:Double)=if(v%1.0==0.0)v.toInt().toString()else String.format(Locale.US,"%.2f",v)
 private fun fmt(v:Double)=when{v>=1e12->String.format(Locale.US,"%.2fT",v/1e12);v>=1e9->String.format(Locale.US,"%.2fB",v/1e9);v>=1e6->String.format(Locale.US,"%.2fM",v/1e6);v>=1e3->String.format(Locale.US,"%.2fK",v/1e3);else->String.format(Locale.US,"%.0f",v)}
}
